INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19401, 'Ezekiel 3:12', 'Ezekiel', 3, 12, '&nbsp;نو بيا د خُدائ پاک روح زۀ اوچت کړم او ما شاته يو دروند آواز واورېدو چې فرمائيل يې، ”د مالِک خُدائ ثناء صِفت او جلال دې د هغۀ په ځائ کښې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19402, 'Ezekiel 3:13', 'Ezekiel', 3, 13, '&nbsp;دا د هغه ژوندى مخلوق د وزرو آوازونه او شور وو چې يو بل سره لګېدل او په خوا کښې يې د هغه پايو آوازونه هم وُو، يو اوچت او دروند شور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19403, 'Ezekiel 3:14', 'Ezekiel', 3, 14, '&nbsp;نو بيا زۀ روح اوچت کړم او د هغه ځائ نه يې ځان سره بوتلم، زۀ ورسره په تريخ مزاج او غصې سره لاړم، خو د مالِک خُدائ زورَور لاس په ما باندې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19404, 'Ezekiel 3:15', 'Ezekiel', 3, 15, '&nbsp;نو زۀ هغه جلاوطنو له راغلم څوک چې په تل ابيب کښې د کبار سيند سره نزدې اوسېدل. زۀ د هغوئ په مينځ کښې د اوو ورځو دپاره چپ کښېناستم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19405, 'Ezekiel 3:16', 'Ezekiel', 3, 16, '&nbsp;د هغه اووۀ ورځو په آخر کښې د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19406, 'Ezekiel 3:17', 'Ezekiel', 3, 17, '&nbsp;او راته يې وفرمائيل چې، ”اے بنى آدمه، ما تۀ د بنى اِسرائيلو دپاره محافظ مقرر کړې، نو هغه کلام واوره کوم چې زۀ تا ته وايم او زما د خوا نه هغوئ ته خبردارے ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19407, 'Ezekiel 3:18', 'Ezekiel', 3, 18, '&nbsp;کۀ چرې زۀ يو بدکاره انسان له خبردارے ورکړم چې تۀ به يقين سره مړ شې، او تۀ هغه د دې نه خبر نۀ کړې او يا ورسره خبرې ونۀ کړې او يا يې د خپلو غلطو لارو نه منع نۀ کړې ترڅو چې د هغۀ ژوند بچ کړې، نو دغه بدکاره به د خپلو ګناهونو په وجه مړ شى، خو تۀ به د هغۀ د مرګ ذمه وار يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19408, 'Ezekiel 3:19', 'Ezekiel', 3, 19, '&nbsp;کۀ تۀ يو بدکاره انسان له خبردارے ورکړې او هغه د خپل شرارت او خرابو لارو نه منع نۀ شى هغه به د خپلو ګناهونو په وجه مړ شى، خو تۀ به خپل ځان بچ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19409, 'Ezekiel 3:20', 'Ezekiel', 3, 20, '&nbsp;او بيا دا هم کۀ چرې يو صادق انسان د خپلو ښو لارو نه واوړى او بد چال چلن شروع کړى، نو زۀ به هغه په امتحان کښې واچوم او هغه به مړ شى. ځکه چې تا هغۀ له خبردارے نۀ دے ورکړے نو هغه به د خپلو ګناهونو په وجه مړ شى او کوم د صداقت کارونه چې هغۀ کړى دى نو هغه به ورته پاتې نۀ شى، او د هغۀ خون به ستا په غاړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19410, 'Ezekiel 3:21', 'Ezekiel', 3, 21, '&nbsp;خو کۀ تۀ صادق انسان ته خبردارے ورکړې چې ګناه مۀ کوه او هغه ستا خبره ومنى او ګناه کول پرېږدى، نو هغه به په يقين سره ژوندے پاتې شى ځکه چې هغۀ ستا خبردارے قبول کړو او تا په دې خپل ژوند بچ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19411, 'Ezekiel 3:22', 'Ezekiel', 3, 22, '&nbsp;نو بيا د مالِک خُدائ لاس په ما وو او هغۀ ما ته وفرمائيل چې، ”پاڅه او وادۍ ته لاړ شه، او زۀ به هلته تا سره خبرې وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19412, 'Ezekiel 3:23', 'Ezekiel', 3, 23, '&nbsp;نو زۀ بيا پاڅېدم او مېدان ته لاړم. او د مالِک خُدائ جلال هلته ولاړ وو، هغه شان لکه کوم جلال چې ما د کبار د سيند سره ليدلے وو نو زۀ په زمکه پړمخې پرېوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19413, 'Ezekiel 3:24', 'Ezekiel', 3, 24, '&nbsp;خو د مالِک خُدائ روح ما له راغے او زۀ يې په خپلو پښو ودرولم. هغۀ ما سره خبرې وکړې او وې فرمائيل چې، ”لاړ شه او خپل ځان دې په خپل کور کښې بند کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19414, 'Ezekiel 3:25', 'Ezekiel', 3, 25, '&nbsp;او اے بنى آدمه، تۀ به په پړو باندې وتړلے شې، تۀ به بند کړے شې د دې دپاره چې تۀ بهر د خلقو مينځ ته ونۀ وځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19415, 'Ezekiel 3:26', 'Ezekiel', 3, 26, '&nbsp;زۀ به ستا ژبه تالو پورې ونښلوم چې تۀ خاموشه پاتې شې او هغوئ ونۀ رټلے شى ځکه چې هغوئ سرکشه قوم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19416, 'Ezekiel 3:27', 'Ezekiel', 3, 27, '&nbsp;خو کله چې زۀ تا سره خبرې وکړم، زۀ به ستا خولۀ کولاو کړم نو تۀ به هغوئ ته دا ووائې چې، مالِک قادر مطلق خُدائ داسې فرمائى. هر څوک چې اورېدل غواړى هغوئ دې واورى او چې څوک اورېدل نۀ غواړى نو نۀ دې اورى، ځکه چې دا يو سرکشه قوم دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19417, 'Ezekiel 4:1', 'Ezekiel', 4, 1, '&nbsp;”نو اوس، اے بنى آدمه، يوه کچه ښخته راواخله، او په خپل مخکښې يې کېږده او پرې د يروشلم د ښار نقشه جوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19418, 'Ezekiel 4:2', 'Ezekiel', 4, 2, '&nbsp;نو بيا د ښار محاصره کېدل په کښې جوړ کړه، ګېرچاپېره ترې نه دېوال جوړ کړه چې يو کس ترې نه نۀ شى تښتېدلے. د دشمن د فوجيانو کېمپ جوړ کړه او دېوال ته د خاورو ډيرى او د قلعې د ماتولو مشينونه تيار کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19419, 'Ezekiel 4:3', 'Ezekiel', 4, 3, '&nbsp;بيا د اوسپنې يو څادر راواخله، دا ستا او د ښار په مينځ کښې د اوسپنې دېوال په شان ولګوه او خپل مخ د ښار طرف ته راوګرځوه. دا به د محاصرې لاندې وى، او تۀ به دا ښار محاصره کوې. دا به د بنى اِسرائيلو دپاره يوه نښه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19420, 'Ezekiel 4:4', 'Ezekiel', 4, 4, '&nbsp;نو بيا په ګس اړخ څمله او د بنى اِسرائيلو ګناهونه په خپل ځان باندې انبار کړه. نو څومره ورځې چې هغوئ ګناه کړې وى د هم هغه ورځو په اندازه په يو اړخ باندې څمله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19421, 'Ezekiel 4:5', 'Ezekiel', 4, 5, '&nbsp;نو ما بيا تۀ د هم هغه ورځو په اندازه د سزا تېرولو دپاره مقرر کړې څومره کالونه چې هغوئ ګناه کړې ده. نو تۀ به لس کم څلور سوه ورځو پورې د بنى اِسرائيلو د ګناهونو سزا زغمې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19422, 'Ezekiel 4:6', 'Ezekiel', 4, 6, '&nbsp;د دې سزا تېرولو نه وروستو بيا دوباره په ښى اړخ د يهوداه د ګناهونو د سزا تېرولو دپاره څمله. نو ما تۀ د څلوېښتو ورځو دپاره مقرر کړې، د يو کال دپاره مې يوه ورځ مقرر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19423, 'Ezekiel 4:7', 'Ezekiel', 4, 7, '&nbsp;نو بيا خپل مخ د يروشلم د محاصرې طرف ته راوګرځوه او په بربنډو لاسونو د هغې خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19424, 'Ezekiel 4:8', 'Ezekiel', 4, 8, '&nbsp;زۀ به تا په پړو وتړم نو تۀ به د يو اړخ نه بل اړخ ته نۀ شې اوړېدلے ترڅو چې تا خپلې د محاصرې ورځې پوره کړې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19425, 'Ezekiel 4:9', 'Ezekiel', 4, 9, '&nbsp;غنم او اوربشې، لوبيا او دال، غوښت او جمدر واخله. او هغه په چاټۍ کښې واچوه او ځان دپاره ترې نه روټۍ جوړوه. دا چې تۀ د لس کم څلورو سوو ورځو دپاره په يو اړخ پروت يې نو په دې دوران کښې د خوراک دپاره استعمالوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19426, 'Ezekiel 4:12', 'Ezekiel', 4, 12, '&nbsp;تۀ دا روټۍ لکه د اوربشو د روټۍ په شان پخوه. کله چې دا روټۍ پخوې نو د خلقو په مخامخ يې د انسان په اوچو غُلو پخه کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19427, 'Ezekiel 4:13', 'Ezekiel', 4, 13, '&nbsp;مالِک خُدائ وفرمائيل چې، ”نو په دې طريقې سره به اِسرائيليان ناپاکه روټۍ د هغه قومونو په مينځ کښې وخورى چرته چې زۀ دوئ شړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19428, 'Ezekiel 4:14', 'Ezekiel', 4, 14, '&nbsp;خو ما ورته وفرمائيل، ”داسې دې نۀ وى، مالِک قادر مطلق خُدايه، ما کله هم خپل ځان نۀ دے ناپاکه کړے. زما د ځوانۍ نه تر اوسه پورې ما هيڅ داسې څيز نۀ دے خوړلے چې هغه مردار شوے وى او يا ځناورو څيرلے وى. هيڅ قسمه حرامه غوښه زما د خولې دننه شوې نۀ ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19429, 'Ezekiel 4:15', 'Ezekiel', 4, 15, '&nbsp;”ډېر ښۀ،“ هغۀ وفرمائيل، ”ښه نو د انسان د غُلو په ځائ خپله روټۍ د غواګانو په سپياکو پخه کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19430, 'Ezekiel 4:16', 'Ezekiel', 4, 16, '&nbsp;نو بيا هغۀ ما ته وفرمائيل، ”اے بنى آدمه، زۀ به په يروشلم روټۍ بنده کړم. هغوئ چې کومه روټۍ خورى نو په ناپ تول او پرېشانۍ سره به يې خورى او کومې اوبۀ چې څښى نو د شمېر په څاڅکو به يې څښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19431, 'Ezekiel 4:17', 'Ezekiel', 4, 17, '&nbsp;ځکه چې خوراک او اوبۀ به په کمېدو وى او هغوئ به د يو بل د شکل نه يريږى، او د خپلې ګناه د سزا د لاندې به د لوږې نه مانده شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19432, 'Ezekiel 5:1', 'Ezekiel', 5, 1, '&nbsp;”اے بنى آدمه، يوه تيره تُوره راواخله او هغه لکه د نائى د چړې په شان د خپل سر او ږيرې د وېښتو خرئيلو دپاره استعمال کړه. او بيا هغه وېښتۀ د يوې تلې په ذريعه په درېو برخو تقسيم کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19433, 'Ezekiel 5:2', 'Ezekiel', 5, 2, '&nbsp;نو کله چې ستا د محاصرې ورځې په ختمېدو شى، د وېښتو درېمه حِصه په ښار کښې دننه وسوزوه. او بله حِصه يې د ښار نه ګېرچاپېره په تُوره ووهه او ذره ذره يې کړه. او بله حِصه په هوا کښې وشينده، ځکه چې زۀ به تُوره دوئ پسې راوکاږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19434, 'Ezekiel 5:3', 'Ezekiel', 5, 3, '&nbsp;خو د وېښتو يو څو تارونه دې د څادر په پلو کښې ونغاړه او ځان سره يې وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19435, 'Ezekiel 5:4', 'Ezekiel', 5, 4, '&nbsp;بيا د دې نه يو څو وېښتۀ راواخله او په اور کښې يې واچوه او وې سوزوه. د هغې نه به اور ټولو بنى اِسرائيلو ته خور شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19436, 'Ezekiel 5:5', 'Ezekiel', 5, 5, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې دا يو مثال دے چې په آئنده کښې به د يروشلم سره څۀ کيږى. يروشلم ما د ټولو قومونو په مينځ کښې پېدا کړے دے او ټول مُلکونه ترې نه ګېرچاپېره پراتۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19437, 'Ezekiel 5:6', 'Ezekiel', 5, 6, '&nbsp;خو په خپل شرارت کښې هغۀ زما د قانون او حکمونو نه سرکشى وکړه د هغه مُلکونو نه هم زيات کوم چې د هغۀ نه ګېرچاپېره پراتۀ دى. هغۀ زما قانون رد کړو او زما د حکمونو تابعدارى يې ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19438, 'Ezekiel 5:7', 'Ezekiel', 5, 7, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، تۀ د نورو قومونو په نسبت زيات سرکشه يې او تا زما په تعليماتو او شريعت عمل ونۀ کړو. خو تا د نورو قومونو د رِواج او اصُولو په مطابق ژوند تېر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19439, 'Ezekiel 5:8', 'Ezekiel', 5, 8, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې زۀ په خپله ستا خلاف شوے يم، اے يروشلمه، زۀ به تا له د نورو قومونو په وړاندې سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19440, 'Ezekiel 5:9', 'Ezekiel', 5, 9, '&nbsp;ځکه زۀ به ستا د هغه ټولو حرام کارو معبودانو په وجه تا سره هغه سلوک وکړم چې ما د دې نه وړاندې کله هم بل چا سره نۀ وى کړے او نۀ به يې بيا چا سره وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19441, 'Ezekiel 5:10', 'Ezekiel', 5, 10, '&nbsp;نو په دې وجه به په تا کښې مور پلار خپل بچى وخورى او بچى به خپل مور پلار وخورى. زۀ به تاسو له سزا درکړم او څوک چې ژوندى پاتې شى هغوئ به تس نس کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19442, 'Ezekiel 5:11', 'Ezekiel', 5, 11, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، زما دې په خپل ذات قسم وى، ځکه چې تاسو د خپلو حرامو کارونو او کرکژن تصويرونو په عبادت کولو سره زما مقدس کور پليت کړو، زۀ به په خپله نۀ په تاسو رحم وکړم، او نۀ به زۀ تاسو ته د رحم په سترګه وګورم او نۀ به تاسو بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19443, 'Ezekiel 5:12', 'Ezekiel', 5, 12, '&nbsp;ستا د خلقو يوه حِصه به په وبا او قحط په تا کښې دننه مړۀ شى، او دوېمه حِصه خلق به دې د ښار د دېوالونو نه بهر په تُوره باندې قتل کړے شى، او درېمه حِصه به زۀ په هوا کښې خوارۀ کړم او په خپله تُوره به يې راګېر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19444, 'Ezekiel 5:13', 'Ezekiel', 5, 13, '&nbsp;نو زما غصه به بيا سړه شى او زما غضب به په آرام شى کله چې زۀ خپل غضب په دوئ نازل کړم، نو هغوئ به په دې پوهه شى چې ما مالِک خُدائ د خپل غېرت د وجې داسې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19445, 'Ezekiel 5:14', 'Ezekiel', 5, 14, '&nbsp;نو د دې نه علاوه به زۀ تا په کنډراتو بدل کړم او کله چې د نورو قومونو خلق ستا په خوا کښې تېريږى نو هغوئ به توبې وباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19446, 'Ezekiel 5:15', 'Ezekiel', 5, 15, '&nbsp;تۀ به نورو خلقو او قومونو ته د مسخرو او پيغورونو، لعنت او يرې يو مثال يې کله چې زۀ خپله سزا او غضب او قهر او سخته رټنه په تا نازله کړم. دا ما مالِک خُدائ فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19447, 'Ezekiel 5:16', 'Ezekiel', 5, 16, '&nbsp;هرکله چې زۀ په تاسو د قحط د مرګونى او تباه کوونکى غشى ګزار وکړم، زۀ به په تا داسې ګزار وکړم چې تا به تباه کړم. زۀ به په تا بيا بيا قحط راولم او ستا د خوراک ذريعه به بنده کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19448, 'Ezekiel 5:17', 'Ezekiel', 5, 17, '&nbsp;زۀ به ستا خلاف قحط او ځنګلى ځناور درولېږم، هغوئ به تاسو بې‌اولاده پرېږدى. وينه تويول او وباګانې به تاسو ته راورسيږى، او زۀ به جنګ ستاسو خلاف راولېږم. مالِک خُدائ په خپله داسې وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19449, 'Ezekiel 6:1', 'Ezekiel', 6, 1, '&nbsp;د مالِک خُدائ کلام بيا په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19450, 'Ezekiel 6:2', 'Ezekiel', 6, 2, '&nbsp;”اے بنى آدمه، خپل مخ دې د بنى اِسرائيلو د غرونو طرف ته واړوه او د هغوئ خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19451, 'Ezekiel 6:3', 'Ezekiel', 6, 3, '&nbsp;او داسې ووايه، اے د بنى اِسرائيل غرونو، د مالِک قادر مطلق خُدائ کلام واورئ. مالِک قادر مطلق خُدائ تاسو غرونو او غونډو، ګړنګونو او درو ته داسې فرمائى، زۀ به اوس ستاسو خلاف تُوره استعمالوم، او زۀ به ستاسو هغه علاقائى عبادتخانې تباه کړم چرته چې تاسو د بُتانو عبادت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19452, 'Ezekiel 6:4', 'Ezekiel', 6, 4, '&nbsp;ستاسو قربان‌ګاه به راوغورزولے شى او ستاسو د خوشبويۍ قربان‌ګاه به ټوټه ټوټه کړے شى. او زۀ به ستاسو خلق ستاسو د معبودانو په وړاندې حلال کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19453, 'Ezekiel 6:5', 'Ezekiel', 6, 5, '&nbsp;زۀ به د بنى اِسرائيلو لاشونه د هغوئ د معبودانو په وړاندې وغورزوم. او زۀ به ستاسو هډوکى ستاسو د قربان‌ګاه سره خوارۀ وارۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19454, 'Ezekiel 6:6', 'Ezekiel', 6, 6, '&nbsp;نو چرته چې تاسو اوسېږئ نو هغه ځائ او ښارونه به کنډر شى او هغه علاقائى عبادتخانې به تباه شى، ستاسو قربان‌ګاه به خرابې او تباه شى، ستاسو معبودان به ټوټه ټوټه او تباه کړے شى، او ستاسو د خوشبويۍ قربان‌ګاه به راوغورزولے شى، او څۀ چې تاسو جوړ کړى دى هغه به جارُو کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19455, 'Ezekiel 6:7', 'Ezekiel', 6, 7, '&nbsp;ستا خلق به په تا کښې ووژلے شى، نو تۀ به په دې پوهه شې چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19456, 'Ezekiel 6:8', 'Ezekiel', 6, 8, '&nbsp;خو زۀ به ځينې خلق بچ کړم، او په تاسو کښې به څۀ خلق د تُورې د مرګ نه وتښتى او په نورو قومونو او مُلکونو کښې به خوارۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19457, 'Ezekiel 6:9', 'Ezekiel', 6, 9, '&nbsp;نو کله چې هغوئ په نورو مُلکونو او قومونو کښې په جلاوطنۍ کښې اوسيږى، نو هغوئ به هلته ما راياد کړى، او په دې به پوهه شى چې هغوئ زۀ په خپلو زناکارو زړونو سره څومره دردولے يم، کوم چې زما نه اوړېدلى دى، او په خپلو سترګو سره به يې د هغه معبودانو سره زنا کوله. د هغه حرام کارونو او د معبودانو د عبادت په وجه کوم چې دوئ کړى دى هغوئ به د خپل ځان نه نفرت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19458, 'Ezekiel 6:10', 'Ezekiel', 6, 10, '&nbsp;نو دوئ به په دې پوهه شى چې زۀ مالِک خُدائ يم او زما خبردارے هسې تشې خبرې نه خو په رښتيا سره مې په دوئ عذاب راوستو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19459, 'Ezekiel 6:11', 'Ezekiel', 6, 11, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ”د غم نه خپل لاسونه وپړقوئ او خپلې پښې په زمکه ودربوئ او د افسوس چغې ووهئ، د بنى اِسرائيلو د هغه ټولو حرامو کارونو په وجه، نو هغوئ به په جنګ او قحط او وبا سره مړۀ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19460, 'Ezekiel 6:12', 'Ezekiel', 6, 12, '&nbsp;هغه څوک چې لرې دى نو هغوئ به په وبا سره مړۀ شى، او هغه څوک چې نزدې دى هغوئ به په جنګ کښې قتل کړے شى، او هغوئ څوک چې بچ پاتې شى نو په قحط سره به مړۀ شى. زۀ به خپل ټول قهر و غضب په هغوئ نازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19461, 'Ezekiel 6:13', 'Ezekiel', 6, 13, '&nbsp;نو هغوئ به په دې پوهه شى چې زۀ مالِک خُدائ يم. کله چې د هغوئ خلق د دوئ د معبودانو او د دوئ د قربان‌ګاه سره مړۀ پراته وى، په هره اوچته غونډۍ او اوچت غر دپاسه او د هرې شنې ونې لاندې او د څېړۍ د ونې لاندې به د دوئ لاشونه پراتۀ وى په هغه ځايونو کښې چرته چې هغوئ خپلو ټولو معبودانو ته د خوشبويۍ نذرانې پېش کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19462, 'Ezekiel 6:14', 'Ezekiel', 6, 14, '&nbsp;او زۀ به خپل لاس د هغوئ په خلاف وراوږد کړم او د هغوئ مُلک به د بيابان نه واخله تر دبله پورې خراب او خاموشه کړم چرته چې هغوئ اوسيږى. نو بيا به هغوئ په دې باندې پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19463, 'Ezekiel 7:1', 'Ezekiel', 7, 1, '&nbsp;نو د مالِک خُدائ کلام بيا په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19464, 'Ezekiel 7:2', 'Ezekiel', 7, 2, '&nbsp;”اے بنى آدمه، مالِک قادر مطلق خُدائ بنى اِسرائيلو ته داسې فرمائى، تباهى دې په سر راغلى ده، ستا په مُلک کښې به هر طرف ته تباهى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19465, 'Ezekiel 7:3', 'Ezekiel', 7, 3, '&nbsp;نو اوس ستاسو آخرى وخت رارسېدلے دے او زۀ به خپل قهر و غضب په تاسو نازل کړم. زۀ به ستاسو د چال چلن په مطابق ستاسو عدالت وکړم او ستاسو د بدو اعمالو په مطابق به تاسو له پوره سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19466, 'Ezekiel 7:4', 'Ezekiel', 7, 4, '&nbsp;نۀ به تۀ زما نه بچ شې او نۀ به زۀ په تا رحم وکړم بلکې ستا د چال چلن او بدو اعمالو سزا به تا له درکړم. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19467, 'Ezekiel 7:5', 'Ezekiel', 7, 5, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، د يو افت دپاسه به بل افت په تاسو راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19468, 'Ezekiel 7:6', 'Ezekiel', 7, 6, '&nbsp;ستاسو اَنجام، ستاسو اَنجام نزدې دے، آخرى وخت مو نزدې دے، وګورئ ستاسو په وړاندې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19469, 'Ezekiel 7:7', 'Ezekiel', 7, 7, '&nbsp;تاسو څوک چې په دې مُلک کښې اوسېږئ ستاسو د ښخېدو ورځ رارسېدلې ده. وخت رارسېدلے دے، هغه ورځ رانزدې شوې ده، دلته کښې د غرونو دپاسه صرف چغې سورې دى، او هيڅ قسمه د خوشحالۍ آوازونه نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19470, 'Ezekiel 7:8', 'Ezekiel', 7, 8, '&nbsp;زۀ به زر خپل قهر په تا نازل کړم، زۀ به تا ته ستا د چال چلن او د بدو اعمالو په مطابق سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19471, 'Ezekiel 7:9', 'Ezekiel', 7, 9, '&nbsp;نۀ به تۀ زما نه بچ شې او نۀ به زۀ په تا رحم وکړم بلکې ستا د چال چلن او بدو اعمالو سزا به تا له درکړم. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ يم څوک چې تاسو وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19472, 'Ezekiel 7:10', 'Ezekiel', 7, 10, '&nbsp;ستاسو اَنجام، ستاسو اَنجام نزدې دے. تباهى مو په سر رارسېدلې ده. ظلم انتها ته رسېدلے دے، او خلق بې‌حده مغروره شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19473, 'Ezekiel 7:11', 'Ezekiel', 7, 11, '&nbsp;د هغوئ د ظلم په وجه د خلقو شرارت زيات شوے دے، يو کس به ترې نه هم پاتې نۀ شى، نۀ د هغوئ خلق، نۀ دولت، او نۀ د هغوئ اهميت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19474, 'Ezekiel 7:12', 'Ezekiel', 7, 12, '&nbsp;هغه وخت راغلے دے، هغه ورځ رارسېدلې ده. اخستونکى دې خوشحالى نۀ کوى او نۀ دې خرڅوونکى خفګان کوى، ځکه چې غضب په ټوله ګڼه باندې راتلونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19475, 'Ezekiel 7:13', 'Ezekiel', 7, 13, '&nbsp;سوداګر به هغه زمکه دوباره وانۀ خلى کومه زمکه چې هغوئ خرڅه کړې ده کۀ چرې دوئ ژوندى هم وى، ځکه چې د مالِک خُدائ فېصله د ټولو دپاره ده او نۀ بدلېدونکې ده. ځکه د خپلو ګناهونو په وجه به يو کس هم خپل ژوند بچ نۀ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19476, 'Ezekiel 7:14', 'Ezekiel', 7, 14, '&nbsp;کۀ څۀ هم کۀ هغوئ بيګل وغږوى او هر څۀ تيار کړى، هيڅوک به جنګ دپاره لاړ نۀ شى، ځکه چې زما غضب په ګڼو خلقو باندې دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19477, 'Ezekiel 7:15', 'Ezekiel', 7, 15, '&nbsp;”د ښار نه بهر جنګونه او په ښار کښې دننه قحط او وباګانې روانې دى، څوک چې د ښار د دېوالونو نه بهر دى هغوئ به د دشمن په تُورو باندې مړۀ شى. او هغه څوک چې د ښار دننه دى د قحط او د وباګانو په وجه به مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19478, 'Ezekiel 7:16', 'Ezekiel', 7, 16, '&nbsp;څوک چې ژوندى پاتې شى هغوئ ټول به غرونو ته پناه اخستلو له لاړ شى، او هر يو به لکه د ګوګوشتکو په شان د خپلې ګناه په وجه زبيرګى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19479, 'Ezekiel 7:17', 'Ezekiel', 7, 17, '&nbsp;د هغوئ په لاسونو کښې به دم نۀ وى، او پښې به يې ريږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19480, 'Ezekiel 7:18', 'Ezekiel', 7, 18, '&nbsp;هغوئ به د ټاټ جامې واغوندى او ټول به يرې اخستى وى. د هغوئ په مخونو به شرم راخور وى او سرونه به يې خرئيلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19481, 'Ezekiel 7:19', 'Ezekiel', 7, 19, '&nbsp;هغوئ به خپل سپين زر لارو کوڅو ته وغورزوى، او د هغوئ سرۀ زر به يو ناپاکه څيز وګڼلے شى. د مالِک خُدائ د غضب په ورځ به د هغوئ سرۀ زر او سپين زر به هغوئ نۀ شى بچ کولے. هغوئ به په دې باندې نۀ خپله لوږه ختمولے شى او نۀ به ورباندې خپله ګېډه مړولے شى. ځکه چې د هم دې څيزونو په وجه هغوئ تير وتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19482, 'Ezekiel 7:20', 'Ezekiel', 7, 20, '&nbsp;هغوئ په خپلو ښکلو زيوراتو باندې فخر کولو چې د هغوئ نه به يې خراب بُتان او مکروه تصويرونه جوړول. نو په دې وجه به زۀ دا څيزونه د هغوئ دپاره پليت او ناپاکه وګرځوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19483, 'Ezekiel 7:21', 'Ezekiel', 7, 21, '&nbsp;زۀ به دا هر څۀ غېرو ته د غنيمت په شکل حواله کړم او د زمکې شريرانو باندې به يې لوټ کړم، او هغوئ به يې پليت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19484, 'Ezekiel 7:22', 'Ezekiel', 7, 22, '&nbsp;زۀ به خپل مخ د دوئ نه واړوم او هغوئ به زما د مقدسو خزانو بې‌حرمتى وکړى، غلۀ به دې ته ننوځى او ناپاکه به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19485, 'Ezekiel 7:23', 'Ezekiel', 7, 23, '&nbsp;زنځيرونه تيار کړه، ځکه چې ټول مُلک د قتل و غارت نه ډک دے او ټول ښار د شر و فساد نه ډک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19486, 'Ezekiel 7:24', 'Ezekiel', 7, 24, '&nbsp;زۀ به د دُنيا د ټولو نه زيات ظالم قومونه راولم چې د دوئ نه د دوئ کورونه په زور قبضه کړى، او زۀ به د دوئ د زورَورو کسانو فخر ختم کړم، او د هغوئ د مقدس ځايونو بې‌حرمتى به وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19487, 'Ezekiel 7:25', 'Ezekiel', 7, 25, '&nbsp;کله چې دهشت راشى، نو هغوئ به د امن او سکون لټون وکړى، خو هيڅ قسم امن به ورته مِلاو نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19488, 'Ezekiel 7:26', 'Ezekiel', 7, 26, '&nbsp;د يو افت دپاسه به بل افت راشى، او د افواه دپاسه به بله افواه خوريږى. هغوئ به په دې کوشش کښې وى چې د نبى رويا واورى، د شريعت تعليم به د اِمام نه ختم شى، او هم داسې د مشرانو مشورې به هم ختمې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19489, 'Ezekiel 7:27', 'Ezekiel', 7, 27, '&nbsp;بادشاه به ماتم کوى، شهزاده به د خفګان جامې اغوستې وى، د مُلک د خلقو لاسونه به رپيږى. زۀ به د هغوئ سره د دوئ د چال چلن په مطابق سلوک کوم، او د هغوئ په خپل معيار او اصُول به د دوئ عدالت وکړم. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19490, 'Ezekiel 8:1', 'Ezekiel', 8, 1, '&nbsp;د جلاوطنۍ په شپږم کال، د شپږمې مياشتې په پينځمه ورځ، کله چې زۀ په خپل کور کښې د يهوداه د مشرانو سره ناست وم چې هلته د مالِک قادر مطلق خُدائ لاس په ما باندې راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19491, 'Ezekiel 8:2', 'Ezekiel', 8, 2, '&nbsp;ما وليدل، او يو شکل مې وليدو چې د انسان په شان ښکارېدو، د ملا نه لاندې هغه د اور په شان ښکارېدو او بره هغه لکه د يوې ځلېدونکې اوسپنې په شان ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19492, 'Ezekiel 8:3', 'Ezekiel', 8, 3, '&nbsp;هغۀ يو څيز راوغزولو چې د لاس په شان ښکارېدو او زۀ يې د سر وېښتو نه راونيولم. روح زۀ د آسمان او زمکې مينځ ته پورته کړم او د خُدائ پاک په رويا کښې يې زۀ يروشلم ته بوتلم، د دننه دربار شمال خوا دروازې ته، چرته چې هغه بُت ولاړ وو کوم چې د خُدائ پاک غېرت راپارولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19493, 'Ezekiel 8:4', 'Ezekiel', 8, 4, '&nbsp;او د بنى اِسرائيلو د خُدائ پاک جلال زما په وړاندې هلته راښکاره شو، لکه څنګه چې ما په رويا کښې د دې نه وړاندې په مېدان کښې ليدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19494, 'Ezekiel 8:5', 'Ezekiel', 8, 5, '&nbsp;نو بيا مالِک خُدائ ما ته وفرمائيل، ”اے بنى آدمه، د شمال خوا ته وګوره،“ نو بيا ما وکتل، د شمال خوا ته د قربان‌ګاه د داخلېدو دروازه کښې ما هغه بُت وليدو د چا خلاف چې د خُدائ پاک غېرت راپارېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19495, 'Ezekiel 8:6', 'Ezekiel', 8, 6, '&nbsp;او هغۀ ما ته وفرمائيل چې، ”اے بنى آدمه، تۀ هغه څۀ وينې چې دوئ يې کوى هغه حرام کارونه چې دوئ يې دلته کوى، نو دا حرام کارونه ما د خپل مقدس کور نه لرې کوى خو تۀ به داسې کارونه وګورې چې د دې نه به زيات خراب وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19496, 'Ezekiel 8:7', 'Ezekiel', 8, 7, '&nbsp;هغۀ زۀ د دربار دروازې ته راوستلم. ما وکتل، ما په دېوال کښې يو سورے وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19497, 'Ezekiel 8:8', 'Ezekiel', 8, 8, '&nbsp;هغۀ ما ته وفرمائيل چې، ”اے بنى آدمه، نو اوس په دېوال کښې دا سورے غټ کړه.“ نو ما بيا په دېوال کښې سورے وکړو او هلته مې يوه پټه دروازه وليدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19498, 'Ezekiel 8:9', 'Ezekiel', 8, 9, '&nbsp;او هغۀ ما ته وفرمائيل چې، ”دننه لاړ شه او هغه شرارت او حرام کارونه وګوره کوم چې هغوئ دلته کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19499, 'Ezekiel 8:10', 'Ezekiel', 8, 10, '&nbsp;نو بيا زۀ دننه لاړم او ومې ليدل چې، په دېوالونو باندې د هر قسمه مارانو او چينجو او پليتو ځناورو تصويرونه جوړ شوى وُو. او ما د بنى اِسرائيلو ټول بُتان وليدل چې هغوئ يې عبادت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19500, 'Ezekiel 8:11', 'Ezekiel', 8, 11, '&nbsp;د بنى اِسرائيل د قوم اويا مشران هلته ولاړ وُو، او د هغوئ په مينځ کښې يازنياه د سافن زوئ هم ولاړ وو. او د هر يو مشر په لاس کښې د خوشبو سوزولو مجمر وو او ترې نه د خوشبو د لوګو لوخړې ختلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');